create table if not exists public.project_state_stage_requirements (id uuid primary key default gen_random_uuid(), project_state_id uuid not null references public.project_states(id) on delete cascade, stage text not null, requirement_key text not null, label text not null, status public.readiness_state not null default 'not_started', required boolean not null default true, notes text, updated_by uuid not null references auth.users(id), updated_at timestamptz not null default now(), unique(project_state_id,stage,requirement_key)); alter table public.project_state_stage_requirements enable row level security; create policy project_state_stage_requirements_select_workspace on public.project_state_stage_requirements for select to authenticated using (exists(select 1 from public.project_states ps where ps.id=project_state_id and public.is_workspace_member(ps.workspace_id))); create policy project_state_stage_requirements_insert_workspace on public.project_state_stage_requirements for insert to authenticated with check (updated_by=auth.uid() and exists(select 1 from public.project_states ps where ps.id=project_state_id and public.is_workspace_member(ps.workspace_id))); create policy project_state_stage_requirements_update_workspace on public.project_state_stage_requirements for update to authenticated using (exists(select 1 from public.project_states ps where ps.id=project_state_id and public.is_workspace_member(ps.workspace_id))) with check (updated_by=auth.uid() and exists(select 1 from public.project_states ps where ps.id=project_state_id and public.is_workspace_member(ps.workspace_id))); grant select,insert,update on public.project_state_stage_requirements to authenticated; comment on table public.project_state_stage_requirements is 'Governed requirement state used by Project State to determine stage completion, blockers, unknowns and required next work.';
